pub(crate) fn layout(wave: i32) -> Option<&'static Layout> { let i=crate::map::level_index(wave); if i>=9 {Some(&LAYOUTS[i-9])}else{None} }

pub(crate) fn build(e: &mut Engine) {
    let s=layout(e.wave).expect("redesigned sector");
    e.map.fill(s.wall); e.floor.fill(0); e.decal.fill(0);
    for &(x,y,w,h) in s.rooms { e.room(x,y,w,h,s.wall, (crate::map::level_index(e.wave)%2) as u8); }
    for &(a,b,vertical_first) in s.edges {
        let (ax,ay,aw,ah)=s.rooms[a]; let (bx,by,bw,bh)=s.rooms[b];
        let (x0,y0,x1,y1)=(ax+aw/2,ay+ah/2,bx+bw/2,by+bh/2);
        if vertical_first { e.hall_v(x0,y0.min(y1),y0.max(y1),-1); e.hall_h(x0.min(x1),x0.max(x1),y1,-1); }
        else { e.hall_h(x0.min(x1),x0.max(x1),y0,-1); e.hall_v(x1,y0.min(y1),y0.max(y1),-1); }
    }
    // Offset machinery islands create strafe cover while preserving central routes.
    for &(x,y,w,h) in &s.rooms[1..] { if w>=9 && h>=9 { e.set_cell(x+3,y+4,s.wall); } }
    for &(x,y) in s.doors {e.set_cell(x,y,8);}
    let (x,y)=s.objective; e.floor[y as usize*MAP_W+x as usize]=2;
}

pub(crate) fn place(e: &mut Engine) {
    let s=layout(e.wave).expect("redesigned sector");
    e.ents.iter_mut().for_each(|en| en.kind=EK_NONE);
    e.ambush.clear();
    let theme=crate::map::level_index(e.wave);
    let machine=match theme { 9|10|13|15|17|19|22|23|24 => EK_PROP_SERVER, 14|20=>EK_PROP_REACTOR, _=>EK_PROP_AC };
    for &(x,y,w,h) in s.rooms {
        for (kind,px,py) in [(machine,x+1,y+1),(EK_PROP_VENT,x+w-2,y+1),(EK_PROP_WLIGHT_C,x+1,y+h-2),(EK_CRATE,x+w-2,y+h-2)] {
            if !e.blocked(px,py) { crate::map::place_item(e,kind,0,px as f32+0.5,py as f32+0.5); }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn rebuilt_graphs_have_loops_room_clearance_and_connected_walkable_floors() {
        let mut e=Engine::new(160,100);
        for wave in 10..=25 {
            e.wave=wave; crate::map::build_level(&mut e);
            let s=layout(wave).unwrap();
            assert!(s.edges.len()>=s.rooms.len(),"level {wave} needs an alternate route");
            assert!(s.rooms.last().unwrap().2>=6 && s.rooms.last().unwrap().3>=9);
            let mut seen=[false;MAP_W*MAP_H];
            let mut queue=vec![(s.start.0 as usize,s.start.1 as usize)];
            while let Some((x,y))=queue.pop() {
                let i=y*MAP_W+x;
                if seen[i] || (e.blocked(x as i32,y as i32) && e.cell(x as i32,y as i32)!=8) {continue;}
                seen[i]=true;
                for (dx,dy) in [(1,0),(-1,0),(0,1),(0,-1)] {
                    let (nx,ny)=(x as i32+dx,y as i32+dy);
                    if nx>0 && ny>0 && nx<(MAP_W-1) as i32 && ny<(MAP_H-1) as i32 {queue.push((nx as usize,ny as usize));}
                }
            }
            for y in 0..MAP_H {for x in 0..MAP_W {
                if !e.blocked(x as i32,y as i32) || e.cell(x as i32,y as i32)==8 {assert!(seen[y*MAP_W+x],"level {wave}: stranded floor {x},{y}");}
                if x==0 || y==0 || x==MAP_W-1 || y==MAP_H-1 {assert!(e.blocked(x as i32,y as i32));}
            }}
            crate::map::place_level(&mut e);
            for en in e.ents.iter().filter(|en|en.kind!=EK_NONE) {assert!(!e.blocked(en.x as i32,en.y as i32),"level {wave}: embedded entity");}
        }
    }
}
